#!/usr/bin/env sh
# Regenerates the LLM context: the `irender` skill's reference files and examples, and
# `llms-full.txt`. Component and icon listings come from the CLI and the rest is copied
# from the READMEs and examples, so they always match the code. Hand-written sources:
# `skills/irender/SKILL.md`, `skills/irender/references/authoring.md`, the skill's
# `counter.yaml` and `wizard.yaml`, and `llms.txt`.
#
#   tools/llm-docs.sh           # rewrite the generated files
#   tools/llm-docs.sh --check   # fail if they're out of date (for CI)
set -eu
cd "$(dirname "$0")/.."

cargo build -q -p irender-cli
# Where cargo put it, which `CARGO_TARGET_DIR` can change.
irender="${CARGO_TARGET_DIR:-target}/debug/irender"

out=$(mktemp -d)
trap 'rm -rf "$out"' EXIT
refs="$out/skills/irender/references"
ex="$out/skills/irender/examples"
mkdir -p "$refs" "$ex"

note() { printf '<!-- Generated by tools/llm-docs.sh from %s. Do not edit. -->\n\n' "$1"; }

{
  note "irender components"
  echo "# Components"
  echo
  echo "Every component with all kits enabled. Each entry: name and summary, then one line per prop (name, type, description), its \`parts\`, and whether it takes \`children\`. Core built-ins come first, then \`ui-*\` (ui-kit), \`ui-chart\` / \`ui-sparkline\` / \`ui-live-data\` (chart-kit), \`ui-flow*\` (flow-kit) and \`ui-icon\` (icon-kit)."
  echo
  echo '```'
  $irender components --ui-kit --chart-kit --flow-kit --icon-kit
  echo '```'
} > "$refs/components.md"

{
  note "irender icons"
  echo "# Icons"
  echo
  echo "Icon names for \`ui-icon\` and the \`icon\` props of ui-kit components (needs \`--icon-kit\`). Write \`pack:name\` (\`logistics:truck\`) or a bare name, which is found in the first pack that has it: \`core\`, \`arrows\` and \`status\` first, then the industry packs alphabetically, \`brands\` last. Each pack: id (title, count): description, then its names."
  echo
  echo '```'
  $irender icons
  echo '```'
} > "$refs/icons.md"

# Copies a README, turning its relative links into GitHub links, since they don't
# resolve from inside the skill.
copy() {
  { note "$1"; perl -pe '
      BEGIN { use File::Spec; ($dir = $ARGV[0]) =~ s{[^/]*$}{} }
      s{\]\((?!https?:|#|mailto:)([^)\s#]+)(#[^)\s]*)?\)}{
        my ($p, $a) = ($1, $2 // "");
        my @out;
        for (split m{/}, "$dir$p") { $_ eq ".." ? pop @out : $_ ne "." && $_ ne "" && push @out, $_ }
        "](https://github.com/kaushik-xs/iRender/blob/main/" . join("/", @out) . "$a)"
      }ge' "$1"; } > "$2"
}
copy README.md "$refs/core.md"
copy crates/irender-ui-kit/README.md "$refs/ui-kit.md"
copy crates/irender-chart-kit/README.md "$refs/chart-kit.md"
copy crates/irender-flow-kit/README.md "$refs/flow-kit.md"
copy crates/irender-icon-kit/README.md "$refs/icon-kit.md"

# Every label a document can translate, read from the kits' source.
{ note "tools/labels.py"; python3 tools/labels.py 2>/dev/null; } > "$refs/labels.md"

cp examples/blocks/login-03.yaml "$ex/login.yaml"
cp examples/blocks/dashboard-01.yaml "$ex/dashboard-01.yaml"
cp examples/blocks/dashboard-01.data.json "$ex/dashboard-01.data.json"

# One file to paste into any model's context: the rules, then the full reference.
{
  echo "# iRender: full LLM context"
  echo
  echo "Generated by tools/llm-docs.sh. Sections: authoring rules, components, core README, then each kit's README. Icon names are in skills/irender/references/icons.md."
  for f in skills/irender/references/authoring.md "$refs/components.md" "$refs/core.md" \
           "$refs/ui-kit.md" "$refs/chart-kit.md" "$refs/flow-kit.md" "$refs/icon-kit.md"; do
    printf '\n\n---\n\n'
    grep -v '^<!-- Generated by' "$f"
  done
} > "$out/llms-full.txt"

generated="skills/irender/references/components.md skills/irender/references/icons.md
skills/irender/references/core.md skills/irender/references/ui-kit.md
skills/irender/references/chart-kit.md skills/irender/references/flow-kit.md
skills/irender/references/icon-kit.md skills/irender/references/labels.md skills/irender/examples/login.yaml
skills/irender/examples/dashboard-01.yaml skills/irender/examples/dashboard-01.data.json llms-full.txt"

if [ "${1:-}" = "--check" ]; then
  stale=0
  for f in $generated; do
    cmp -s "$out/$f" "$f" || { echo "out of date: $f"; stale=1; }
  done
  [ $stale = 0 ] || { echo "run tools/llm-docs.sh"; exit 1; }
  echo "LLM docs are up to date"
else
  for f in $generated; do
    mkdir -p "$(dirname "$f")"
    cp "$out/$f" "$f"
  done
  echo "wrote $(echo $generated | wc -w | tr -d ' ') files"
fi
